explanation:
This complete React/JSX App demonstrates shared data and local navigation:
```react
function App() {
  const [view, setView] = React.useState('home');
  const [books] = React.useState(['Forest Guide']);
  return <main>
    <nav>
      <button onClick={() => setView('home')}>Home</button>
      <button onClick={() => setView('saved')}>Saved</button>
    </nav>
    <h1>{view === 'home' ? 'Library' : 'Saved books'}</h1>
    <ul>{books.map(book => <li key={book}>{book}</li>)}</ul>
  </main>;
}
```
Saved changes the heading while Forest Guide remains. The expression condition ? first : second is a conditional choice, called a ternary. It chooses which heading text to render.

This second App is a complete sample loader for the same runner:
```react
function App() {
  const [status, setStatus] = React.useState('idle');
  const [books, setBooks] = React.useState([]);
  const [error, setError] = React.useState('');
  const latest = React.useRef(0);
  function load(mode) {
    const id = ++latest.current;
    setStatus('loading');
    setError('');
    setTimeout(() => {
      if (id !== latest.current) return;
      if (mode === 'error') {
        setError('Could not load the library.');
        setStatus('error');
        return;
      }
      setBooks(mode === 'empty' ? [] : ['Forest Guide']);
      setStatus('success');
    }, mode === 'slow' ? 120 : 20);
  }
  return <main>
    <button onClick={() => load('slow')}>Slow sample</button>
    <button onClick={() => load('error')}>Error sample</button>
    <button onClick={() => load('empty')}>Empty sample</button>
    {status === 'loading' && <p>Loading…</p>}
    {status === 'error' && <p role="alert">{error}</p>}
    {status === 'success' && books.length === 0 && <p>No books.</p>}
    {status === 'success' && <ul>
      {books.map(book => <li key={book}>{book}</li>)}
    </ul>}
  </main>;
}
```
Empty sample first shows loading, then No books. Error sample first shows loading, then the error message.

