function App() {
  const items = React.useMemo(() => Array.from({ length: 1000 }, (_, i) => `Book ${i}`), []);
  const [query, setQuery] = React.useState("Book 99");
  const [repeat, setRepeat] = React.useState(0);
  const [totals, setTotals] = React.useState({ baseline: 0, memoized: 0 });
  const previous = React.useRef({ baseline: null, memoized: null, baselineTotal: 0, memoizedTotal: 0 });
  function measure() {
    let examined = 0;
    const matches = items.filter(item => { examined += 1; return item.toLowerCase().includes(query.toLowerCase()); });
    return { matches, examined };
  }
  const baseline = React.useMemo(measure, [items, query, repeat]);
  // TODO: choose dependencies that exclude the unrelated repeat counter
  const memoized = React.useMemo(measure, [items, query, repeat]);
  React.useEffect(() => {
    const last = previous.current;
    if (last.baseline !== baseline) last.baselineTotal += baseline.examined;
    if (last.memoized !== memoized) last.memoizedTotal += memoized.examined;
    last.baseline = baseline; last.memoized = memoized;
    setTotals({ baseline: last.baselineTotal, memoized: last.memoizedTotal });
  }, [baseline, memoized]);
  const same = baseline.matches.length === memoized.matches.length && baseline.matches.every((value, index) => value === memoized.matches[index]);
  return <main><label>Search <input value={query} onChange={e => setQuery(e.target.value)} /></label>
    <button onClick={() => setRepeat(value => value + 1)}>Repeat same search</button>
    <p>Baseline total comparisons: {totals.baseline}</p><p>Memoized total comparisons: {totals.memoized}</p>
    <p>Same results: {same ? "yes" : "no"}</p><p>Matches: {memoized.matches.length}</p>
    <ul>{memoized.matches.slice(0, 10).map(item => <li key={item}>{item}</li>)}</ul></main>;
}

